from pathlib import Path
pages = {
'membership/family': ('Family membership', '<p class=\"price\">"'$100 <span>/ year</span></p><h2>Discovery, together.</h2><p>Unlimited entry for two adults and children under 18.</p><p>Family membership keeps discovery close to home.</p><p>Pricing effective January 1, 2025.</p><a class="text-link" href="/#join-form">Continue with Family <span aria-hidden="true">→</span></a>'"'),
'privacy': ('Privacy', '<p>This local membership form validates your email in your browser. It does not send your email to a service or save it to browser storage.</p><p>Continuing records a local event containing only the event name and the Family plan. The event is cleared when you reload the page.</p>'),
'accessibility': ('Accessibility', '<p>You can navigate this page using your keyboard. Use Tab to move between links and form controls, and Enter to activate them.</p><p>The membership form provides labeled fields, visible focus indicators, and text feedback for errors and confirmation. The layout adapts to narrow screens and text zoom.</p>')
}
for route, (title, content) in pages.items():
    path = Path(route); path.mkdir(parents=True, exist_ok=True)
    (path/'index.html').write_text(f'''<"'!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | Northstar Museum</title><link rel="stylesheet" href="/styles.css"></head><body><a class="skip-link" href="#main">Skip to content</a><header id="site-header" class="site-header wrap"><a class="wordmark" href="/">Northstar <span>Museum</span></a><nav aria-label="Main navigation"><a href="/">Membership</a></nav></header><main id="main" class="document wrap" tabindex="-1"><h1>{title}</h1>{content}</main><footer id="site-footer" class="site-footer wrap"><p>Northstar Museum</p><div><a href="/privacy">Privacy</a><a href="/accessibility">Accessibility</a></div></footer></body></html>'"''')
PY"

